#include "dhcp_core.h"
static uint32_t get32(const uint8_t*p){return((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
int dhcp_parse(const uint8_t*p,uint32_t n,struct dhcp_view*out){if(!p||!out||n<240||p[2]==0||p[2]>16)return -1;if(get32(p+236)!=0x63825363U)return -1;out->op=p[0];out->hardware_type=p[1];out->hardware_length=p[2];out->xid=get32(p+4);out->client_ip=get32(p+12);out->your_ip=get32(p+16);out->server_ip=get32(p+20);out->client_hardware=p+28;out->message_type=0;uint8_t ended=0;for(uint32_t i=240;i<n;){uint8_t code=p[i++];if(code==0)continue;if(code==255){ended=1;break;}if(i>=n)return -1;uint8_t len=p[i++];if((uint32_t)len>n-i)return -1;if(code==53){if(len!=1||out->message_type)return -1;out->message_type=p[i];}i+=len;}if(!ended||!out->message_type)return -1;return 0;}
